.path-seal{position:absolute;right:19px;top:17px;width:42px;height:42px;display:grid;place-items:center;border:1px solid #d5e1d4;border-radius:50%;background:#eef4eb;color:#47735d;font:23px 'Ma Shan Zheng',serif}
