.path-level{width:100%;display:flex;justify-content:space-between;align-items:center;padding:11px 0;border-top:1px solid #eceee6;border-bottom:1px solid #eceee6;color:#78857b;font-size:9px;letter-spacing:.7px}
.path-level b{color:#355e4d;font-size:11px;letter-spacing:0}
.spirit-path .path-level b{color:#71658f}
.path-card .inventory-row{margin-top:5px}
.path-card>.action-btn{width:100%;margin-top:10px;min-height:38px}
.path-note{margin-top:15px}
.path-note .feature-stats{margin-top:17px}
.feature-card{padding:21px;border:1px solid #30483d;border-radius:9px;background:linear-gradient(145deg,#243d34,#172a25);color:#f3f2e7;box-shadow:var(--shadow)}
.feature-card .eyebrow{color:#b6c4a8}
