.feature-stats{display:flex;flex-wrap:wrap;gap:8px 18px;padding-top:12px;border-top:1px solid rgba(220,229,212,.16)}
.feature-stats span{display:grid;gap:4px;color:#aab8a9;font-size:8px;letter-spacing:.65px}
.feature-stats b{color:#e5d7a9;font-size:11px;letter-spacing:0}
.inventory-row{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:10px 0;border-bottom:1px solid #eceee6;color:#7b877e;font-size:10px}
.inventory-row:last-child{border-bottom:0}
.inventory-row b{color:#334a3e;font-size:10px;text-align:right}
.combat-panel{min-height:260px}
.enemy-card{display:flex;align-items:center;gap:19px;margin-top:22px;padding:18px;border:1px solid #e8e8df;border-radius:8px;background:linear-gradient(120deg,#f8f6ee,#fffefa)}
.enemy-glyph{width:78px;height:78px;flex-shrink:0;display:grid;place-items:center;border:1px solid #e7dcc0;border-radius:50%;background:radial-gradient(circle,#fffdf5,#f0ead8);color:#806f4f;font:40px 'Ma Shan Zheng',serif}
