@media(max-width:720px){.path-choice-grid{grid-template-columns:1fr}.path-card>p{min-height:0}.enemy-card{gap:13px;padding:14px}.enemy-glyph{width:61px;height:61px;font-size:32px}.enemy-info h2{font-size:19px}.combat-actions .action-btn:last-child{flex:1 1 100%}}
