input.newString:
function sectData(s = state) { return sects[s.sectId] || sects.azure; }
function gearStat(stat) { return gearCatalog.reduce((sum, item) => sum + (item.stat === stat && state.equipment?.[item.id]?.owned ? item.value * state.equipment[item.id].level : 0), 0); }
function attackDamage(base) { return Math.round((base + gearStat('attack')) * (1 + sectData().attack + state.sectRank * .03)); }
function rateFor(s = state) { return (0.8 + s.upgrades.sutra * .45 + (s.pathLevels?.spirit || 0) * .2) * (1 + s.boosts + gearStat('qi') + sectData(s).qi + s.sectRank * .02) * (s.active ? 1 : .2); }
function currentBand(stage = state.stage) { return realmBands.find(b => stage >= b.start && stage <= b.end); }

