for (const [sect, spell] of [['azure', 'Cloudburst Palm'], ['crimson', 'Blazing Phoenix'], ['jade', 'Lotus Bind']]) {
  saved = await page.evaluate(() => JSON.parse(localStorage.getItem('stillwater-cultivator-v1')));
  saved.sectId = sect; saved.enemy = null; saved.mission = null;
  await openWithState(saved);
  await page.locator('[data-view="combat"]').first().click();
  if (!(await text('#view-combat')).includes(spell)) throw new Error(`${sect} sect spell was not rendered`);
  await page.locator('[data-action="seek-enemy"]').click();
  saved = await page.evaluate(() => JSON.parse(localStorage.getItem('stillwater-cultivator-v1')));
  if (saved.enemy.sect !== sect) throw new Error(`${sect} selected a ${saved.enemy.sect} beast`);
}

// Mission tracking, rewards, and gear purchases/refinement.
await openWithState({ qi: 100, stones: 500, stage: 0, active: false, lastSeen: Date.now(), sectId: 'azure', sectTokens: 100, hp: 50, maxHp: 65 });
