await page.locator('[data-action="accept-mission"][data-id="hunt3"]').click();
for (let i = 0; i < 3; i++) {
  saved = await page.evaluate(() => JSON.parse(localStorage.getItem('stillwater-cultivator-v1')));
  saved.enemy = { name: `Mission Beast ${i}`, icon: '獸', sect: saved.sectId, hp: 1, maxHp: 1, damage: 0, stones: 0, rep: 0, drop: null };
  await openWithState(saved);
  await page.locator('[data-view="combat"]').first().click();
  await page.locator('[data-action="attack"][data-style="body"]').click();
}
saved = await page.evaluate(() => JSON.parse(localStorage.getItem('stillwater-cultivator-v1')));
if (saved.mission.progress !== 3) throw new Error('Mission beast-defeat progress failed');
const stonesBeforeClaim = saved.stones;
await page.locator('[data-view="sect"]').first().click();
await page.locator('[data-action="claim-mission"]').click();
saved = await page.evaluate(() => JSON.parse(localStorage.getItem('stillwater-cultivator-v1')));
if (saved.mission !== null || saved.stones !== stonesBeforeClaim + 80 || saved.sectTokens !== 108 || saved.sectRep < 12) throw new Error('Mission reward payout failed');
const healthBeforePants = saved.maxHp;
await page.locator('[data-action="buy-gear"][data-id="sword"]').click();
await page.locator('[data-action="buy-gear"][data-id="pants"]').click();
saved = await page.evaluate(() => JSON.parse(localStorage.getItem('stillwater-cultivator-v1')));
if (!saved.equipment.sword.owned || !saved.equipment.pants.owned || saved.maxHp !== healthBeforePants + 10) throw new Error('Gear purchase / health bonus failed');
const stonesBeforeUpgrade = saved.stones;
await page.locator('[data-action="upgrade-gear"][data-id="sword"]').click();
saved = await page.evaluate(() => JSON.parse(localStorage.getItem('stillwater-cultivator-v1')));
if (saved.equipment.sword.level !== 2 || saved.stones !== stonesBeforeUpgrade - 70) throw new Error('Gear upgrade cost / level failed');

// Jade Lotus spell damages, spends qi, and heals after taking a counter-hit.
saved.sectId = 'jade'; saved.qi = 50; saved.hp = 40;
saved.enemy = { name: 'Spell Test Beast', icon: '獸', sect: 'jade', hp: 1000, maxHp: 1000, damage: 1, stones: 0, rep: 0, drop: null };
await openWithState(saved);
await page.locator('[data-view="combat"]').first().click();
await page.locator('[data-action="cast-spell"]').click();
saved = await page.evaluate(() => JSON.parse(localStorage.getItem('stillwater-cultivator-v1')));
if (saved.qi !== 40 || saved.enemy.hp >= 1000 || saved.hp !== 47) throw new Error('Jade spell damage / qi / healing failed: ' + JSON.stringify({ qi: saved.qi, enemyHp: saved.enemy?.hp, hp: saved.hp }));

await page.setViewportSize({ width: 390, height: 844 });
await page.locator('.mobile-nav [data-view="sect"]').click();
await page.waitForFunction(() => !document.getElementById('toast').classList.contains('show'));
await page.screenshot({ path: '/tmp/opencode/stillwater-sect-mobile.png', fullPage: true });
const overflow = await page.evaluate(() => ({ scroll: document.documentElement.scrollWidth, client: document.documentElement.clientWidth }));
const cardLayout = await page.evaluate(() => ({ sectCards: [...document.querySelectorAll('.sect-choice')].map(e => e.getBoundingClientRect().width), gearCards: [...document.querySelectorAll('.gear-card')].map(e => e.getBoundingClientRect().width) }));
if (overflow.scroll > overflow.client + 1) throw new Error('Sect Hall mobile horizontal overflow: ' + JSON.stringify(overflow));
if (cardLayout.sectCards.some(w => w <= 0) || cardLayout.gearCards.some(w => w <= 0)) throw new Error('Sect Hall cards are not visible on mobile: ' + JSON.stringify(cardLayout));
